"""Liveness (``/healthz``) and readiness (``/readyz``) probes."""

from __future__ import annotations

import logging
from typing import Annotated

from fastapi import APIRouter, Depends
from sqlalchemy import text
from sqlalchemy.orm import Session

from app.core.db import get_db
from app.core.errors import ServiceUnavailableError
from app.schemas import ErrorResponse, HealthResponse

router = APIRouter(tags=["health"])

logger = logging.getLogger("app.health")


@router.get("/healthz", response_model=HealthResponse, summary="Liveness probe")
def healthz() -> HealthResponse:
    """Report that the process is alive; never touches the database."""
    return HealthResponse(status="ok")


@router.get(
    "/readyz",
    response_model=HealthResponse,
    summary="Readiness probe",
    responses={503: {"model": ErrorResponse, "description": "Database is not ready"}},
)
def readyz(db: Annotated[Session, Depends(get_db)]) -> HealthResponse:
    """Report readiness after a trivial ``SELECT 1`` succeeds."""
    try:
        db.execute(text("SELECT 1"))
    except Exception:
        logger.warning("readiness check failed")
        raise ServiceUnavailableError("Database is not ready") from None
    return HealthResponse(status="ready")

"""Short-code generation and validation helpers.

Codes are drawn from the base62 alphabet with a CSPRNG (``secrets``); the ``random``
module is deliberately never used so codes stay unguessable.
"""

import re
import secrets
import string

ALPHABET = string.ascii_letters + string.digits

RESERVED_CODES = frozenset(
    {"healthz", "readyz", "api", "docs", "redoc", "openapi.json", "static", "favicon.ico"}
)

CODE_PATTERN = re.compile(r"^[A-Za-z0-9]{1,32}$")


def generate_code(length: int) -> str:
    """Return a random base62 code of ``length`` characters."""
    return "".join(secrets.choice(ALPHABET) for _ in range(length))


def is_reserved(code: str) -> bool:
    """Return True if ``code`` collides (case-insensitively) with a reserved path segment."""
    return code.casefold() in RESERVED_CODES


def is_valid_code_format(code: str) -> bool:
    """Return True if ``code`` could be a stored short code (1-32 base62 characters)."""
    return bool(CODE_PATTERN.fullmatch(code))

"""Persistence access for click events. Flushes only; never commits or rolls back."""

from datetime import datetime

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from app.models.click_event import ClickEvent


class ClickRepository:
    """Insert and aggregate ``ClickEvent`` rows within the caller's transaction."""

    def __init__(self, session: Session) -> None:
        self.session = session

    def add(self, event: ClickEvent) -> ClickEvent:
        """Add and flush a click event."""
        self.session.add(event)
        self.session.flush()
        return event

    def count_for_link(self, link_id: int) -> int:
        """Return the all-time number of click events for a link."""
        stmt = select(func.count(ClickEvent.id)).where(ClickEvent.link_id == link_id)
        return int(self.session.execute(stmt).scalar_one())

